import { ref, reactive, watch } from 'vue';
export default {
  props: {
    loading: Boolean,
    errors: {
      type: Object,
      default: () => ({})
    }
  },
  emits: ['register'],
  setup(props, {
    emit
  }) {
    const username = ref('');
    const email = ref('');
    const password = ref('');
    const password2 = ref('');
    const localErrors = reactive({
      username: [],
      email: [],
      password: [],
      password2: [],
      general: null
    });
    watch(() => props.errors, newErrors => {
      Object.keys(localErrors).forEach(key => {
        localErrors[key] = Array.isArray(newErrors[key]) ? newErrors[key] : [newErrors[key]];
      });
      if (newErrors.general) {
        localErrors.general = newErrors.general;
      }
    }, {
      deep: true
    });
    const clearError = field => {
      localErrors[field] = [];
      localErrors.general = null;
    };
    const submitForm = () => {
      emit('register', {
        username: username.value,
        email: email.value,
        password: password.value,
        password2: password2.value
      });
    };
    return {
      username,
      email,
      password,
      password2,
      errors: localErrors,
      submitForm,
      clearError
    };
  }
};
